 "اگر رکورد مقصد پیدا نشد، این به معنای شکست قطعی نیست. اقدام را برای بررسی دستی ارجاع بده. لغو و ارسال مجدد در این حالت مجاز نیست.": "If the destination record was not found, this does not mean a definite failure. Escalate the action for manual review. Cancellation and re-dispatch are not permitted in this state.",
