 "ایجادشده از": "Created from",
 "این": "this",
 "این PASS فقط گیرندگان پیش‌نویس را بررسی می‌کند؛ گیرندگان فرم انتشار مستقل از این پنل دوباره کنترل می‌شوند. این بررسی مجوز سازمانی یا ارسال واقعی را تأیید نمی‌کند.": "This PASS only checks the draft recipients; the publication form's recipients are re-checked independently of this panel. This check does not confirm organizational authorization or real dispatch.",
 "این ابزارها صرفاً پیش‌نویس آزمایشی ثبت می‌کنند. مدل و داده معتبر برای پیش‌بینی یا شبیه‌سازی عملیاتی متصل نیست.": "These tools only record test drafts. No valid model or data is connected for operational forecasting or simulation.",
 "این اقدام انجام نشد: دسترسی، وضعیت یا اطلاعات لازم معتبر نیست.": "This action was not performed: access, status or required information is not valid.",
 "این اقدام متوقف نیست.": "This action is not paused.",
 "این انتقال وضعیت مجاز نیست": "This status transition is not allowed",
 "این بخش به داده مرجع، مجوز و قرارداد مربوط به CMMS نیاز دارد و هنوز گردش‌کار کاملش پیاده نشده است. داده خیالی به‌عنوان تاریخچه/شاهد تجهیزات نمایش داده نمی‌شود.": "This section requires CMMS reference data, permissions and a contract, and its full workflow is not yet implemented. Fictional data is not shown as equipment history/evidence.",
 "این بخش فقط نمایشی است و مجوز واقعی صادر نمی‌کند.": "This section is demo only and does not grant real permissions.",
 "این بخش یک شبیه‌سازی فرانت‌اند است؛ ثبت گزارش، اجرای واقعی یا نتیجه تأییدشده محسوب نمی‌شود.": "This section is a frontend simulation; it does not count as a submitted report, real execution or verified result.",
 "این بیمارستان": "this hospital",
 "این تنظیمات فقط نحوه نمایش تاریخ را تغییر می‌دهد؛ مبنای ذخیره داده ثابت است.": "These settings only change how dates are displayed; the data storage basis stays the same.",
 "این ثبت فقط پیش‌نویس نمایشی است.": "This entry is only a demo draft.",
 "این جدول نشان‌دهنده عبور واقعی از گیت نیست؛ Promote و فعال‌سازی بدون اثبات کنترل‌ها مجاز نیست.": "This table does not reflect actually passing the gates; Promote and activation are not allowed without proof of controls.",
 "این داده‌های نمایشی متعلق به": "This demo data belongs to",
 "این درخواست خارج از دامنه‌ی فعلی شماست؛ سؤال را به بیمارستان فعلی محدود کنید.": "This request is outside your current scope; limit the question to the current hospital.",
 "این سند مصنوعی است؛ تغییر وظیفه یا منبع واقعی انجام نمی‌شود.": "This is a synthetic document; no real-world action is taken.",
 "این سه دارایی داده ثابت ساختگی مخصوص آزمون فرانت‌اند هستند؛ تعلق سازمانی، تازگی، خرابی، استفاده و امتیاز ریسک واقعی تأیید نشده است. همه ردیف‌ها فقط در سایت انتخابی به صورت نمونه قابل مرورند.": "These three assets are fixed synthetic data for frontend testing only; organizational ownership, freshness, failure, utilization and real risk score are not verified. All rows can be browsed as samples only within the selected site.",
 "این صفحه صرفاً درخواست/پیش‌نویس محلی ذخیره می‌کند. هیچ نقش، مجوز یا تفویض واقعی ایجاد یا فعال نمی‌شود. تأیید مستقل، احراز هویت و موتور سیاست متصل نیستند.": "This page only saves local requests/drafts. No real role, permission or delegation is created or activated. Independent approval, authentication and the policy engine are not connected.",
 "این عملیات فقط در محیط نمایشی است؛ دلیل در تاریخچه ذخیره می‌شود.": "Demo only: reason is stored in local activity history.",
 "این فرایند هیچ fetch، اتصال PACS/HIS، اجرای ETL یا پرس‌وجوی بیمارستانی ندارد. فقط 4 رخداد بدون داده بیمار را در حافظه مرورگر بررسی می‌کند.": "This process performs no fetch, PACS/HIS connection, ETL run or hospital query. It only checks 4 events without patient data in browser memory.",
 "این فرم فقط درخواست قرارداد مصنوعی ایجاد می‌کند؛ قرارداد اجرایی، داده واقعی یا اعتماد به اتصال منبع برقرار نمی‌کند.": "This form only creates a synthetic contract request; it does not establish an executable contract, real data or trust in the source connection.",
 "این فرم فقط یک پیش‌نویس نمایشی می‌سازد؛ سفارش خرید، رزرو موجودی یا انتقال واقعی انجام نمی‌شود.": "This form only creates a demo draft; no real purchase order, stock reservation or transfer is made.",
 "این فضای کار نمایشی است و نتیجه بررسی واقعی تأیید نشده است.": "This workspace is a demo and no real review outcome has been verified.",
 "این فهرست از سرویس رسمی هویت دریافت نشده و نباید مبنای صدور دسترسی باشد.": "This list was not obtained from the official identity service and must not be the basis for granting access.",
 "این متریک مستقل از وظایف و هشدارهای ICU است.": "This metric is separate from ICU tasks and alerts.",
 "این مرحله باید به شناسه یک پیش‌نویس گزارش در همین دامنه متصل باشد.": "This step must be linked to a report draft ID in the same scope.",
 "این مسیر جانشین مجوز واقعی T3 نیست؛ حالت برگشت‌ناپذیر عمداً پیشنهاد جبران ایجاد نمی‌کند.": "This path does not replace real T3 authorization; irreversible mode intentionally does not create a compensation proposal.",
 "این موارد فقط نامزد تطبیق‌اند و نتیجه قطعی نیستند.": "These items are only reconciliation candidates, not a definitive result.",
 "این نسخه برای اعتبارسنجی نمایشی واجد شرایط نیست.": "This version is not eligible for demo validation.",
