 "این نسخه متریک قبلاً ثبت شده است.": "This metric version is already registered.",
 "این نما فقط چارچوب گردش کار است؛ تأیید CAPA و گزارش بالینی واقعی انجام نمی‌شود.": "This view is only a workflow framework; no real CAPA approval or clinical reporting takes place.",
 "این هشدار از وضعیت فعلی پیشنهاد محاسبه شده و رخداد ممیزیِ مستقل نیست.": "This alert is computed from the proposal's current status and is not an independent audit event.",
