 "این پرونده فقط در مرورگر ذخیره می‌شود. فهرست Playbookها مثال طراحی است، نه نسخه مصوب. درستی فرضیه، شواهد، هویت بازبین و نتیجه تغییر وضعیت هشدار به‌صورت عملیاتی تأیید نشده‌اند.": "This case is stored only in the browser. The Playbook list is a design example, not an approved version. The correctness of the hypothesis, the evidence, the reviewer's identity and the outcome of the alert status change have not been operationally verified.",
 "این پرونده یک شبیه‌سازی کیفیت داده است؛ بدون شواهد اجرا و راستی‌آزمایی مستقل به حالت بسته منتقل نمی‌شود.": "This case is a data quality simulation; it cannot move to closed without execution evidence and independent verification.",
