 "این پیشنهاد پیش از ارسال لغو شد:": "This proposal was cancelled before dispatch:",
 "این پیش‌نویس یا وضعیت بررسی‌شده به‌معنای سفارش خرید یا انتقال اجراشده نیست.": "This draft or reviewed status does not mean an executed purchase order or transfer.",
 "این کنترل‌ها درخواست و گزارش داخلی آزمایشی ثبت می‌کنند؛ تعویق، انتساب، تشدید یا تغییر وضعیت واقعی هشدار فقط پس از تأیید سامانه کنترل مجاز است. «مشاهده تغییر» هرگز اثبات اثرِ اقدام نیست.": "These controls record trial internal requests and reports; actual snoozing, assignment, escalation or status change of an alert is only permitted after control system approval. \"Observed change\" is never proof of an action's effect.",
